import{_ as t,o as a,c as r,a3 as o}from"./chunks/framework.DQ-7HQaQ.js";const u=JSON.parse('{"title":"AI models, tokens and your budget","description":"Compare Groq, Gemini, OpenAI, Anthropic and DeepSeek, understand token bills, and build a small RAG app without surprise costs.","frontmatter":{"title":"AI models, tokens and your budget","description":"Compare Groq, Gemini, OpenAI, Anthropic and DeepSeek, understand token bills, and build a small RAG app without surprise costs."},"headers":[],"relativePath":"students/ai-costs.md","filePath":"students/ai-costs.md","lastUpdated":1794433168000}'),s={name:"students/ai-costs.md"};function n(i,e,l,d,c,p){return a(),r("div",null,[...e[0]||(e[0]=[o(`<h1 id="good-answers-small-budget-no-surprises" tabindex="-1">Good answers. Small budget. No surprises. <a class="header-anchor" href="#good-answers-small-budget-no-surprises" aria-label="Permalink to &quot;Good answers. Small budget. No surprises.&quot;">​</a></h1><p><strong>Start with Groq for a small public-data experiment. Keep Gemini as another free-tier option.</strong> Then compare results, not just prices. The cheapest answer is not useful if its citations are wrong.</p><p>This is optional project help, not a requirement to buy a subscription or change your assignment. You can <a href="./reference">test retrieval locally</a> without any key. Hosted generation is a separate step; this page does not claim that every provider is already implemented in the local lab.</p><h2 id="choose-a-starting-point" tabindex="-1">Choose a starting point <a class="header-anchor" href="#choose-a-starting-point" aria-label="Permalink to &quot;Choose a starting point&quot;">​</a></h2><ul><li><strong>Groq:</strong> a useful first stop for fast interactive experiments with a free API allowance. Groq hosts models; <code>openai/gpt-oss-20b</code> on Groq is not a ChatGPT subscription or an OpenAI API bill.</li><li><strong>Gemini:</strong> another free API starting point for permitted public or synthetic material. Check the data terms before uploading anything.</li><li><strong>OpenAI, Anthropic and DeepSeek:</strong> useful comparison candidates when you have API access and a small approved budget. Don&#39;t assume that a free chatbot account supplies free API calls.</li></ul><p>Try the same five source-backed questions with two models. Record citation correctness, unsupported claims, latency and <strong>cost per acceptable answer</strong>. A higher price alone does not prove higher quality.</p><h2 id="compare-actual-models-not-company-names" tabindex="-1">Compare actual models, not company names <a class="header-anchor" href="#compare-actual-models-not-company-names" aria-label="Permalink to &quot;Compare actual models, not company names&quot;">​</a></h2><p><strong>Official prices checked November 11, 2026. USD per 1 million tokens.</strong> These are selected examples, not an exhaustive catalog or a ranking of equal capabilities. Standard text generation, uncached input, no batch discount; taxes, hosting, embedding and tool charges excluded. Confirm the live pricing and model availability before enabling billing.</p><p><em>On a narrow screen, swipe the table sideways to see all prices.</em></p><table tabindex="0"><thead><tr><th>Provider and example model</th><th style="text-align:right;">Input / 1M</th><th style="text-align:right;">Output / 1M</th><th style="text-align:right;">1,000 example answers*</th></tr></thead><tbody><tr><td><a href="https://console.groq.com/docs/models" target="_blank" rel="noreferrer">Groq: <code>openai/gpt-oss-20b</code></a></td><td style="text-align:right;">$0.075</td><td style="text-align:right;">$0.30</td><td style="text-align:right;">$0.375</td></tr><tr><td><a href="https://console.groq.com/docs/models" target="_blank" rel="noreferrer">Groq: <code>openai/gpt-oss-120b</code></a></td><td style="text-align:right;">$0.15</td><td style="text-align:right;">$0.60</td><td style="text-align:right;">$0.75</td></tr><tr><td><a href="https://aistudio.google.com/docs/pricing#gemini-2.5-flash-lite" target="_blank" rel="noreferrer">Google: <code>gemini-2.5-flash-lite</code></a></td><td style="text-align:right;">$0.10</td><td style="text-align:right;">$0.40</td><td style="text-align:right;">$0.50</td></tr><tr><td><a href="https://developers.openai.com/api/docs/models/gpt-5.4-mini" target="_blank" rel="noreferrer">OpenAI: <code>gpt-5.4-mini</code></a></td><td style="text-align:right;">$0.75</td><td style="text-align:right;">$4.50</td><td style="text-align:right;">$4.50</td></tr><tr><td><a href="https://platform.claude.com/docs/en/about-claude/pricing" target="_blank" rel="noreferrer">Anthropic: <code>claude-haiku-5-5</code></a></td><td style="text-align:right;">$0.10</td><td style="text-align:right;">$0.50</td><td style="text-align:right;">$0.55</td></tr><tr><td><a href="https://api-docs.deepseek.com/quick_start/pricing/" target="_blank" rel="noreferrer">DeepSeek: <code>deepseek-flash</code>, peak</a></td><td style="text-align:right;">$0.30</td><td style="text-align:right;">$1.20</td><td style="text-align:right;">$1.50</td></tr><tr><td><a href="https://api-docs.deepseek.com/quick_start/pricing/" target="_blank" rel="noreferrer">DeepSeek: <code>deepseek-flash</code>, off-peak</a></td><td style="text-align:right;">$0.15</td><td style="text-align:right;">$0.60</td><td style="text-align:right;">$0.75</td></tr></tbody></table><p>*Each answer uses <strong>3,000 input + 500 total billed output tokens</strong>. This is a calculation, not measured performance or a promise about how many visible words you receive. Different tokenizers can count the same text differently; measure real usage when comparing providers.</p><p><strong>Conditions matter.</strong> Haiku 5.5&#39;s row applies to prompts up to 100,000 tokens; above that its base input/output rates are $0.50/$2.50. DeepSeek&#39;s current <code>deepseek-flash</code> resolves to V4.1-Flash-1017. Its peak window is weekdays 01:00–04:00 and 06:00–10:00 UTC, excluding Chinese public holidays; other hours are off-peak. Use peak rates when budgeting conservatively. OpenAI regional processing has an additional uplift. Cached input, cache writes/storage, search and other tools can change every provider&#39;s bill. Don&#39;t price an entire application from its cheapest cached-token headline.</p><h2 id="what-does-free-actually-mean" tabindex="-1">What does “free” actually mean? <a class="header-anchor" href="#what-does-free-actually-mean" aria-label="Permalink to &quot;What does “free” actually mean?&quot;">​</a></h2><p><strong>Groq:</strong> the <a href="https://console.groq.com/docs/rate-limits" target="_blank" rel="noreferrer">published free limits</a> for both GPT-OSS examples are 30 requests/minute, 1,000/day, 8,000 tokens/minute and 200,000/day, applied at the organization level. Your console is authoritative. A 3,500-token request can exhaust the token allowance well before the request allowance. Queue calls; respect <code>429</code> and retry guidance rather than creating accounts to bypass limits.</p><p><strong>Gemini:</strong> the selected Flash-Lite model lists free input/output with rate limits. Google&#39;s pricing page says free-tier content can be used to improve products, while paid-tier content is not used for that purpose, subject to its terms. Free access is not permission to upload classmates&#39; work or private records.</p><p><strong>OpenAI:</strong> the selected model lists no free API tier. ChatGPT is the user-facing app; the API powers your code. Treat billing separately. Some eligible subscriptions have a limited <a href="https://help.openai.com/en/articles/20001626-api-credits-benefit-for-eligible-chatgpt-subscriptions" target="_blank" rel="noreferrer">API-credit benefit</a>; check eligibility and activation rather than assuming your plan covers it.</p><p><strong>Anthropic and DeepSeek:</strong> budget for paid API usage unless your account explicitly shows usable credits. Trials, grants or subscriber benefits are not a permanent free allowance. Check credit expiry and what happens when it runs out.</p><p>For <strong>every</strong> provider, review age/region eligibility, account permissions and current terms. Groq&#39;s <a href="https://console.groq.com/docs/your-data" target="_blank" rel="noreferrer">data policy</a> distinguishes default inference handling from retention for certain features, reliability and abuse monitoring. “Not used for training” and “never stored” are different promises. Use public/synthetic documents for this lab.</p><h2 id="read-your-bill-before-you-grow-it" tabindex="-1">Read your bill before you grow it <a class="header-anchor" href="#read-your-bill-before-you-grow-it" aria-label="Permalink to &quot;Read your bill before you grow it&quot;">​</a></h2><p>A token is a small piece of text, not necessarily a word. Code, punctuation and different languages tokenize differently. Use the provider&#39;s tokenizer or response usage counts, not a word-count guess.</p><ul><li><strong>Input:</strong> instructions + question + conversation history + retrieved passages + tool schemas/results.</li><li><strong>Output:</strong> generated tokens, including billed reasoning/thinking where applicable. A short visible reply can still consume more.</li><li><strong>Context window:</strong> how much a request can hold, not a free allowance or a target to fill.</li><li><strong>Rate limit:</strong> how quickly you can call the service. A low price does not prevent throttling.</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cost = input_tokens / 1,000,000 × input_price</span></span>
<span class="line"><span>     + billed_output_tokens / 1,000,000 × output_price</span></span>
<span class="line"><span>     + separately billed tools, storage and other services</span></span></code></pre></div><p>For Groq 20B, one example costs <code>3000/1M × $0.075 + 500/1M × $0.30 = $0.000375</code>. That is <strong>0.0375 cents</strong>, not 0.375 dollars. At 1,000 calls, it is <strong>$0.375</strong> before other charges. Free-tier eligibility may reduce the actual generation bill to zero, but not remove quotas.</p><p>A class of 30 students testing 100 times each makes 3,000 calls: <strong>$1.125</strong> at that paid rate. Three model calls per answer triples the estimate to <strong>$3.375</strong>; doubling again for retries and evaluation makes it <strong>$6.75</strong>. This is planning math, not a shared-key recommendation.</p><p>For a product, start with <code>active users × answers/user × calls/answer</code>. Add embeddings, hosting, storage, support and payment fees. A $10 hosting bill may exceed token costs in a small demo. Track cost per successful answer and reserve room for failures before choosing a selling price.</p><h2 id="can-graphs-or-vectors-lower-the-token-bill" tabindex="-1">Can graphs or vectors lower the token bill? <a class="header-anchor" href="#can-graphs-or-vectors-lower-the-token-bill" aria-label="Permalink to &quot;Can graphs or vectors lower the token bill?&quot;">​</a></h2><p><strong>Yes, by helping you select better evidence, not by making information magically free.</strong> A vector is a numeric representation used to find similar content; a graph stores entities and relationships you can traverse. Usually the model receives selected text or serialized facts, not the entire database or its vector index. That text still becomes input tokens.</p><p>Think of <strong>useful evidence per token</strong>, rather than a universal “density of meaning” score. A compact graph fact such as <code>Course A → requires → Course B</code> can replace a long irrelevant passage, but may omit the exception, date or source that makes the fact true. Keep provenance and retrieve the supporting passage when needed. Graph construction, summaries and embeddings can themselves cost money; stale or incorrect summaries can make cheap answers worse.</p><p><strong>Illustrative comparison:</strong> suppose a long-context approach sends 20,000 input tokens per question, while targeted retrieval sends 3,000. At Groq 20B&#39;s listed paid input rate, that is $1.50 versus $0.225 for 1,000 questions: <strong>$1.275 saved on input</strong>, holding output fixed. These are assumed token counts, not a benchmark proving graph search beats vector search. A good SQL filter may save just as much. If building the index costs more than the savings, a tiny demo may never break even.</p><p>Compare SQL filters, keyword search, vector search, graph traversal and combinations on the <strong>same questions and source snapshot</strong>. Measure retrieval quality, citation accuracy, input/output tokens, indexing cost, latency and abstention when evidence is missing. Count only correct, adequately supported answers as successes. <a href="./data-choices">Choose a database and retrieval approach</a>.</p><h2 id="keep-the-budget-and-the-key-under-control" tabindex="-1">Keep the budget and the key under control <a class="header-anchor" href="#keep-the-budget-and-the-key-under-control" aria-label="Permalink to &quot;Keep the budget and the key under control&quot;">​</a></h2><ol><li>Start with a tiny request and inspect its actual usage. Set a small spending limit where supported and alerts before it. An alert is not necessarily a hard stop.</li><li>Enforce server-side limits on prompt size, retrieved chunks, output tokens, concurrent requests and calls per user. Limit agent iterations and retries. Require authentication and abuse controls before exposing a paid generation endpoint. Never silently switch from free to paid.</li><li>Keep keys on your server in ignored environment files or deployment secrets. Ignore secret files using both <code>.gitignore</code> and <code>.dockerignore</code>; a Git ignore rule does not stop Docker <code>COPY</code>. Never put them in Git, screenshots, frontend JavaScript, <code>VITE_*</code> variables, Docker images or Pages. Rotate an exposed key immediately.</li><li>Keep one provider adapter behind your application&#39;s interface. Configure provider/model on the server. Test differences in streaming, tools, JSON, token accounting and errors; “OpenAI-compatible” does not mean identical.</li><li>Log model/version, usage, latency and estimated cost, not secrets or sensitive prompt text. Compare logs with the billing dashboard.</li></ol><p><strong>Try it:</strong> run five questions, calculate the actual cost, then halve your retrieved context. Did the bill fall? Did citation quality survive? Keep the improvement only if both the evidence and the budget make sense. This is a learning exercise, not another graded deliverable.</p>`,33)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
